import{_ as o,a0 as r,w as s,s as u,ao as x,I as t,x as l,a1 as a,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"11个Linux基础面试问题 | LCTT x X-CMD","titleTemplate":false,"description":"11个Linux基础面试问题 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"11个Linux基础面试问题 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"11个Linux基础面试问题 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/11 Basic Linux Interview Questions and Answers","title":"11个Linux基础面试问题","tag":"201311","desc":""},"relativePath":"201311/11 Basic Linux Interview Questions and Answers.md","filePath":"[post].md"}'),d={name:"201311/11 Basic Linux Interview Questions and Answers.md"};function p(h,i,L,c,m,b){const n=r("Link");return s(),u("div",null,[i[11]||(i[11]=x('<h1 id="_11个linux基础面试问题" tabindex="-1">11个Linux基础面试问题 <a class="header-anchor" href="#_11个linux基础面试问题" aria-label="Permalink to “11个Linux基础面试问题”">​</a></h1><h3 id="q-1-linux-操作系统的核心是什么" tabindex="-1">Q.1: Linux 操作系统的核心是什么? <a class="header-anchor" href="#q-1-linux-操作系统的核心是什么" aria-label="Permalink to “Q.1: Linux 操作系统的核心是什么?”">​</a></h3><ul><li>Shell</li><li>Kernel</li><li>Command</li><li>Script</li><li>Terminal</li></ul><blockquote><p><strong>答</strong>: 内核(Kernel)是Linux 操作系统的核心。Shell是一个命令行解释器，命令（Command）是针对计算机的指令，脚本(Script)是存储在文件中的命令的集合，终端(Termial)是命令行接口。</p></blockquote><h3 id="q-2-linus-torvalds-都创建过什么东东" tabindex="-1">Q.2: Linus Torvalds 都创建过什么东东? <a class="header-anchor" href="#q-2-linus-torvalds-都创建过什么东东" aria-label="Permalink to “Q.2: Linus Torvalds 都创建过什么东东?”">​</a></h3><ul><li>Fedora</li><li>Slackware</li><li>Debian</li><li>Gentoo</li><li>Linux</li></ul><blockquote><p><strong>答</strong>: Linux Torvalds 创建了Linux，Linux是所有上述操作系统的核心，同样也是其他一些Linux 操作系统的核心。</p></blockquote><h3 id="q-3-torvalds-使用c-语言编写了linux内核的大部分代码-是这样吗" tabindex="-1">Q.3: Torvalds，使用C++语言编写了Linux内核的大部分代码，是这样吗? <a class="header-anchor" href="#q-3-torvalds-使用c-语言编写了linux内核的大部分代码-是这样吗" aria-label="Permalink to “Q.3: Torvalds，使用C++语言编写了Linux内核的大部分代码，是这样吗?”">​</a></h3><blockquote><p><strong>答</strong>: 不! Linux内核包含了12,020,528行代码，其中注释占去了2,151,595 行。因此剩下的9,868,933 行就是纯代码了。而其中7,896,318行都是用C语言写的。</p></blockquote><p>剩下的1,972,615行则是使用C++，汇编，Perl, Shell Script, Python, Bash Script, HTML, awk, yacc, lex, sed等。</p><p><strong>注</strong>：代码行数每天都在变动，平均每天超过3,509行代码添加到内核。</p><h3 id="q-4-起初-linux-是为-intel-x86-架构编写的-但是后来比其他操作系统移植的硬件平台都多-是这样吗" tabindex="-1">Q.4: 起初，Linux 是为 Intel X86 架构编写的，但是后来比其他操作系统移植的硬件平台都多，是这样吗 ？ <a class="header-anchor" href="#q-4-起初-linux-是为-intel-x86-架构编写的-但是后来比其他操作系统移植的硬件平台都多-是这样吗" aria-label="Permalink to “Q.4: 起初，Linux 是为 Intel X86 架构编写的，但是后来比其他操作系统移植的硬件平台都多，是这样吗 ？”">​</a></h3><blockquote><p><strong>答</strong>: 是的，我同意。Linux那时候是为x86机器写的，而且现已移至到所有类型的平台。今天超过90%的超级计算机都在使用Linux。Linux在移动手机和平板电脑领域前景广阔。事实上我们被Linux包围着，远程遥控，太空科学，研究，Web，桌面计算等等，举之不尽。</p></blockquote><h3 id="q-5-编辑-linux-内核合法吗" tabindex="-1">Q.5: 编辑 Linux 内核合法吗? <a class="header-anchor" href="#q-5-编辑-linux-内核合法吗" aria-label="Permalink to “Q.5: 编辑 Linux 内核合法吗?”">​</a></h3><blockquote><p><strong>答</strong>: 是的，内核基于GPL发布，任何人都可以基于GPL允许的权限随意编辑内核。Linux内核属于免费开源软件（FOSS）。</p></blockquote><h3 id="q-6-unix和linux操作系统-本质上的不同在哪里" tabindex="-1">Q.6: UNIX和Linux操作系统，本质上的不同在哪里？### <a class="header-anchor" href="#q-6-unix和linux操作系统-本质上的不同在哪里" aria-label="Permalink to “Q.6: UNIX和Linux操作系统，本质上的不同在哪里？###”">​</a></h3><blockquote><p><strong>答</strong>: Linux操作系统属于免费开源软件，内核是由 Linus Torvalds 和开源社区共同开发的。当然我们不能说UNIX操作系统和免费开源软件（FOSS）无关，BSD 就是基于 FOSS 范畴的 UNIX 的变种。而且大公司如 Apple，IBM，Oracle，HP等，都在为UNIX内核贡献代码。</p></blockquote><h3 id="q-7-挑出来一个与众不同的来" tabindex="-1">Q. 7: 挑出来一个与众不同的来. <a class="header-anchor" href="#q-7-挑出来一个与众不同的来" aria-label="Permalink to “Q. 7: 挑出来一个与众不同的来.”">​</a></h3><ul><li>HP-UX</li><li>AIX</li><li>OSX</li><li>Slackware</li><li>Solaris</li></ul><blockquote><p><strong>答</strong> : Slackware。 HP-UX, AIX, OSX, Solaris 分别是由 HP, IBM, APPLE, Oracle 开发的，并且都是UNIX的变种. Slackware 则是一个Linux操作系统.</p></blockquote><h3 id="q-8-linux-不会感染病毒吗" tabindex="-1">Q.8: Linux 不会感染病毒吗? <a class="header-anchor" href="#q-8-linux-不会感染病毒吗" aria-label="Permalink to “Q.8: Linux 不会感染病毒吗?”">​</a></h3><blockquote><p><strong>答</strong> : 当然会! 这个地球上不存在不会感染病毒的操作系统。但是Linux以迄今为止病毒数量少而著称，是的，甚至比UNIX还要少。Linux榜上有名的病毒只有60-100个，而且没有一个病毒在传播蔓延。Unix粗略估计有85-120个。</p></blockquote><h3 id="q-9-linux-属于哪种类型的操作系统" tabindex="-1">Q.9: Linux 属于哪种类型的操作系统? <a class="header-anchor" href="#q-9-linux-属于哪种类型的操作系统" aria-label="Permalink to “Q.9: Linux 属于哪种类型的操作系统?”">​</a></h3><ul><li>多用户</li><li>多任务</li><li>多线程</li><li>以上所有</li><li>以上都不是</li></ul><blockquote><p><strong>答</strong> : 以上所有。Linux是一个支持多用户，可以同时运行多个进程执行多个任务的操作系统。</p></blockquote><h3 id="q-10-一般的-linux-命令的语法格式是" tabindex="-1">Q.10: 一般的 Linux 命令的语法格式是： <a class="header-anchor" href="#q-10-一般的-linux-命令的语法格式是" aria-label="Permalink to “Q.10: 一般的 Linux 命令的语法格式是：”">​</a></h3><ul><li>command [选项] [参数]</li><li>command 选项 [参数]</li><li>command [选项] [参数]</li><li>command 选项 参数</li></ul><blockquote><p><strong>答</strong> : Linux 命令的正确语法是, Command [选项] [参数]。</p></blockquote><h3 id="q-11-挑出来一个与众不同的来" tabindex="-1">Q.11: 挑出来一个与众不同的来. <a class="header-anchor" href="#q-11-挑出来一个与众不同的来" aria-label="Permalink to “Q.11: 挑出来一个与众不同的来.”">​</a></h3><ul><li>Vi</li><li>vim</li><li>cd</li><li>nano</li></ul><blockquote><p><strong>答</strong> : cd 与其他命令不同。Vi，vim和 nano都是编辑器，用于编辑文档，而cd是用于切换目录的命令。</p></blockquote><p>就这么多了。上述问题你学到手几个？效果如何？我们期待着你的评论。下周，会有新的问题，让我们拭目以待。保持健康，锁定链接，记得来<strong>Tecmint</strong>哦。</p><hr>',33)),t("p",null,[i[1]||(i[1]=l("via: ",-1)),a(n,{href:"http://www.tecmint.com/basic-linux-interview-questions-and-answers/"},{default:e(()=>[...i[0]||(i[0]=[l("http://www.tecmint.com/basic-linux-interview-questions-and-answers/",-1)])]),_:1})]),t("p",null,[i[4]||(i[4]=l("译者：",-1)),a(n,{href:"https://github.com/l3b2w1"},{default:e(()=>[...i[2]||(i[2]=[l("l3b2w1",-1)])]),_:1}),i[5]||(i[5]=l(" 校对：",-1)),a(n,{href:"https://github.com/jasminepeng"},{default:e(()=>[...i[3]||(i[3]=[l("jasminepeng",-1)])]),_:1})]),t("p",null,[i[8]||(i[8]=l("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[6]||(i[6]=[l("LCTT",-1)])]),_:1}),i[9]||(i[9]=l(" 原创翻译，",-1)),a(n,{href:"http://linux.cn/"},{default:e(()=>[...i[7]||(i[7]=[l("Linux中国",-1)])]),_:1}),i[10]||(i[10]=l(" 荣誉推出",-1))])])}const T=o(d,[["render",p]]);export{g as __pageData,T as default};
